import { validateDiscount } from "./src/validator.ts";

async function readStdin(): Promise<string> {
    return new Promise((resolve, reject) => {
        let data = "";
        process.stdin.setEncoding("utf8");
        process.stdin.on("data", (chunk) => (data += chunk));
        process.stdin.on("end", () => resolve(data));
        process.stdin.on("error", reject);
    });
}

async function main() {
    const raw = await readStdin();
    let payload: unknown;
    try {
        payload = JSON.parse(raw);
    } catch (e) {
        console.log(`INVALID: ${(e as Error).message}`);
        process.exit(0);
    }

    const result = validateDiscount(payload);
    if (result.valid) {
        console.log("VALID");
        console.log(JSON.stringify(result.data));
    } else {
        const summary = result.errors.summary || String(result.errors);
        console.log(`INVALID: ${summary}`);
    }
    process.exit(0);
}

main();
